1	package govflow
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10	)
11	
12	// 本文件为 tally 首次计票“保存失败”补充命令行回归保障，覆盖两类必须可区分
13	// 的结果（普通文本与 --json 两种输出模式一致）：
14	//
15	//   - 失败发生在状态文件替换之前：结论没有写入。命令退出码 1、stdout 没有任何
16	//     计票结果、stderr 保留具体保存原因（既不能说成投票尚未截止，也不能说成
17	//     结论已写入）；随后查询仍是 voting、没有计票结论；恢复保存条件后在 210
18	//     再次计票才形成首次通过结论，首次计票时间为 210，不沿用失败尝试的 200。
19	//   - 状态文件已替换成功、只在随后的目录同步失败：结论已写入但持久性未确认。
20	//     命令同样退出码 1、stdout 仍没有计票结果、stderr 说明“已写入但持久性未
21	//     确认”并保留具体原因；恢复正常读取条件后查询应看到 passed 与 tallied_at=200
22	//     的完整结论；210 再次计票只返回已有的 200 结论，不改成 210，也不退回 voting。
23	//
24	// 业务场景复用 cliVoteCreateArgs：资金库 1000；带委托的有效转账提案
25	// alice/bob/carol/dave 原始权重 300/200/100/400，bob、carol 委托给 alice，
26	// 法定人数 600、投票窗口 [100,200)、时间锁 300、动作 transfer:audits:100；
27	// dave 在 130 投反对（归集 400），alice 在 170 投赞成（归集 600）。截止时刻
28	// 200 的正常首次计票结论应为赞成 600、反对 400、参与 1000 的通过结论。
29	
30	// cliTallyInit 跨进程准备上述场景：初始化资金库、创建提案、保存两张窗口内票据
31	// （dave 反对@130 在前，alice 赞成@170 在后）。
32	func cliTallyInit(t *testing.T, binary, state, id string) {
33		t.Helper()
34		if _, se, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
35			t.Fatalf("init exit=%d: %s", code, se)
36		}
37		if _, se, code := runCLI(t, binary, state, cliVoteCreateArgs(id)...); code != 0 {
38			t.Fatalf("create-vote exit=%d: %s", code, se)
39		}
40		if _, se, code := runCLI(t, binary, state, "vote", "--id", id,
41			"--voter", "dave", "--choice", "against", "--now", "130"); code != 0 {
42			t.Fatalf("dave against ballot exit=%d: %s", code, se)
43		}
44		if _, se, code := runCLI(t, binary, state, "vote", "--id", id,
45			"--voter", "alice", "--choice", "for", "--now", "170"); code != 0 {
46			t.Fatalf("alice for ballot exit=%d: %s", code, se)
47		}
48	}
49	
50	// cliTallyQueryJSON 以全新进程用 JSON 查询提案并解析成视图。
51	func cliTallyQueryJSON(t *testing.T, binary, state, id string) *VoteProposalView {
52		t.Helper()
53		so, se, code := runCLI(t, binary, state, "proposal", "--id", id, "--json")
54		if code != 0 {
55			t.Fatalf("json proposal query exit=%d: %s", code, se)
56		}
57		var v VoteProposalView
58		if err := json.Unmarshal([]byte(so), &v); err != nil {
59			t.Fatalf("proposal json is not valid: %v\n%s", err, so)
60		}
61		return &v
62	}
63	
64	// cliTallyAssertShape 断言提案的窗口、时间锁、法定人数、总权重、成员原始权重、
65	// 委托关系与动作原文仍是创建时的样子，不被任何保存失败改写。
66	func cliTallyAssertShape(t *testing.T, v *VoteProposalView) {
67		t.Helper()
68		if v.Quorum != 600 || v.StartAt != 100 || v.Deadline != 200 ||
69			v.TimelockEnd != 300 || v.TotalWeight != 1000 {
70			t.Fatalf("proposal parameters changed: %+v", v)
71		}
72		if !sameActions(v.Actions, []string{"transfer:audits:100"}) {
73			t.Fatalf("actions = %v, want the original transfer action text", v.Actions)
74		}
75		wantMembers := map[string]MemberView{
76			"alice": {ID: "alice", Weight: 300, Path: []string{"alice"}, Delegate: "alice", Direct: ""},
77			"bob":   {ID: "bob", Weight: 200, Path: []string{"bob", "alice"}, Delegate: "alice", Direct: "alice"},
78			"carol": {ID: "carol", Weight: 100, Path: []string{"carol", "alice"}, Delegate: "alice", Direct: "alice"},
79			"dave":  {ID: "dave", Weight: 400, Path: []string{"dave"}, Delegate: "dave", Direct: ""},
80		}
81		if len(v.Members) != len(wantMembers) {
82			t.Fatalf("members = %+v, want the original four members", v.Members)
83		}
84		for _, m := range v.Members {
85			want, ok := wantMembers[m.ID]
86			if !ok {
87				t.Fatalf("unexpected member %+v", m)
88			}
89			if m.Weight != want.Weight || m.Delegate != want.Delegate ||
90				m.Direct != want.Direct || !sameActions(m.Path, want.Path) {
91				t.Fatalf("member %s changed: got %+v want %+v", m.ID, m, want)
92			}
93		}
94	}
95	
96	// cliTallyAssertBallots 断言两张已保存票据的代表、归集权重、选择、首次时间与
97	// 顺序全部保留：dave 反对 400@130 在前，alice 赞成 600@170 在后。
98	func cliTallyAssertBallots(t *testing.T, v *VoteProposalView) {
99		t.Helper()
100		if len(v.Ballots) != 2 {
101			t.Fatalf("ballots = %+v, want exactly the two saved ballots", v.Ballots)
102		}
103		first, second := v.Ballots[0], v.Ballots[1]
104		if first.Representative != "dave" || first.Weight != 400 || first.Support || first.VotedAt != 130 {
105			t.Fatalf("first ballot = %+v, want dave against weight=400 voted_at=130", first)
106		}
107		if second.Representative != "alice" || second.Weight != 600 || !second.Support || second.VotedAt != 170 {
108			t.Fatalf("second ballot = %+v, want alice for weight=600 voted_at=170", second)
109		}
110	}
111	
112	// cliTallyAssertText 断言文本查询的关键字与查询状态一致：state、提案参数、
113	// 成员/委托路径、票据、动作原文以及（有结论时）计票行都按文本格式呈现。
114	func cliTallyAssertText(t *testing.T, binary, state, id, wantState string, tallyLine string) {
115		t.Helper()
116		to, te, code := runCLI(t, binary, state, "proposal", "--id", id)
117		if code != 0 {
118			t.Fatalf("text proposal query exit=%d: %s", code, te)
119		}
120		if !strings.Contains(to, "state="+wantState) {
121			t.Fatalf("text query must show state=%s:\n%s", wantState, to)
122		}
123		for _, want := range []string{
124			"quorum=600 voting=[100,200) timelock_end=300 actions=1 total_weight=1000",
125			"member alice weight=300 representative=self",
126			"member bob weight=200 path=bob->alice",
127			"member carol weight=100 path=carol->alice",
128			"member dave weight=400 representative=self",
129			"action 0: transfer:audits:100",
130			"ballot representative=dave choice=against weight=400 voted_at=130",
131			"ballot representative=alice choice=for weight=600 voted_at=170",
132		} {
133			if !strings.Contains(to, want) {
134				t.Fatalf("text proposal view missing %q:\n%s", want, to)
135			}
136		}
137		// dave 票据必须排在 alice 之前。
138		davePos := strings.Index(to, "ballot representative=dave")
139		alicePos := strings.Index(to, "ballot representative=alice")
140		if davePos < 0 || alicePos < 0 || davePos > alicePos {
141			t.Fatalf("text ballots must preserve dave-before-alice order:\n%s", to)
142		}
143		if tallyLine == "" {
144			if strings.Contains(to, "tally for=") {
145				t.Fatalf("text query must contain no tally line:\n%s", to)
146			}
147		} else if !strings.Contains(to, tallyLine) {
148			t.Fatalf("text query missing tally line %q:\n%s", tallyLine, to)
149		}
150	}
151	
152	// cliTallyAssertVoting 以全新进程分别用 JSON 与文本查询，断言提案仍是 voting、
153	// 没有任何计票结论，且票据、成员、委托关系与动作原文全部保留。
154	func cliTallyAssertVoting(t *testing.T, binary, state, id string) {
155		t.Helper()
156		v := cliTallyQueryJSON(t, binary, state, id)
157		if v.State != "voting" || v.Tally != nil {
158			t.Fatalf("state=%s tally=%+v, want voting with no tally conclusion", v.State, v.Tally)
159		}
160		cliTallyAssertBallots(t, v)
161		cliTallyAssertShape(t, v)
162		cliTallyAssertText(t, binary, state, id, "voting", "")
163	}
164	
165	// cliTallyAssertPassed 以全新进程分别用 JSON 与文本查询，断言提案为 passed，
166	// 计票结论为赞成 600、反对 400、参与 1000、法定人数 600、首次计票时间恰为
167	// wantTalliedAt；票据、成员、委托关系与动作原文仍完整保留。
168	func cliTallyAssertPassed(t *testing.T, binary, state, id string, wantTalliedAt int64) {
169		t.Helper()
170		v := cliTallyQueryJSON(t, binary, state, id)
171		if v.State != "passed" || v.Tally == nil {
172			t.Fatalf("state=%s tally=%+v, want passed with the written conclusion", v.State, v.Tally)
173		}
174		if !v.Tally.Passed || v.Tally.ForWeight != 600 || v.Tally.AgainstWeight != 400 ||
175			v.Tally.Turnout != 1000 || v.Tally.Quorum != 600 || v.Tally.TalliedAt != wantTalliedAt {
176			t.Fatalf("tally = %+v, want passed for=600 against=400 turnout=1000 quorum=600 tallied_at=%d",
177				v.Tally, wantTalliedAt)
178		}
179		cliTallyAssertBallots(t, v)
180		cliTallyAssertShape(t, v)
181		line := fmt.Sprintf("tally for=600 against=400 turnout=1000 => passed tallied_at=%d", wantTalliedAt)
182		cliTallyAssertText(t, binary, state, id, "passed", line)
183	}
184	
185	// cliTallyAssertFundsUntouched 断言计票（无论成功还是保存失败）从不执行转账：
186	// 资金库仍是 1000、没有任何收款账户余额、没有执行凭据。
187	func cliTallyAssertFundsUntouched(t *testing.T, binary, state string) {
188		t.Helper()
189		bo, be, bc := runCLI(t, binary, state, "balances", "--json")
190		if bc != 0 || !strings.Contains(bo, `"treasury": 1000`) || strings.Contains(bo, "audits") {
191			t.Fatalf("tally must not move funds, exit=%d stderr=%s:\n%s", bc, be, bo)
192		}
193		ro, re, rc := runCLI(t, binary, state, "receipts", "--json")
194		if rc != 0 || strings.TrimSpace(ro) != "[]" {
195			t.Fatalf("tally must not produce execution receipts, exit=%d stderr=%s:\n%s", rc, re, ro)
196		}
197	}
198	
199	// TestCLITallyPreReplaceSaveFailure：首次计票的保存失败发生在状态文件替换之前
200	// （目录不可写，临时文件都无法创建）。普通文本与 --json 两种模式都必须：
201	//   - 退出码 1，stdout 没有任何计票结果；
202	//   - stderr 保留具体保存原因（permission denied），不能说成投票尚未截止
203	//     （still open），也不能说成结论已写入（durability not confirmed）；
204	//   - 原状态文件字节不变、不遗留临时文件；
205	//   - 随后查询仍是 voting、没有计票结论，票据/成员/委托/动作完整保留；
206	//   - 恢复保存条件后在 210 再次计票才形成首次通过结论，首次计票时间为 210，
207	//     不沿用失败尝试的 200；再次计票（300）仍返回 210 结论。
208	//
209	// 全过程计票不执行转账，资金库与收款账户余额不变、不产生执行凭据。
210	func TestCLITallyPreReplaceSaveFailure(t *testing.T) {
211		binary := buildCLI(t)
212		state := filepath.Join(t.TempDir(), "treasury.json")
213		const id = "gip-tally-cli-pre"
214		cliTallyInit(t, binary, state, id)
215	
216		// 记录失败前的完整状态文件字节：两次失败尝试后它必须原样保留。
217		good, err := os.ReadFile(state)
218		if err != nil {
219			t.Fatal(err)
220		}
221	
222		// 目录不可写：提交在状态文件替换之前（创建临时文件）失败。该失败不写入任何
223		// 内容，因此文本与 JSON 两次独立调用都应得到同样的“尚未写入”失败，且提案
224		// 始终保持 voting。
225		makeDirUnwritable(t, state)
226		for _, tc := range []struct {
227			name string
228			args []string
229		}{
230			{"text", []string{"tally", "--id", id, "--now", "200"}},
231			{"json", []string{"tally", "--id", id, "--now", "200", "--json"}},
232		} {
233			t.Run(tc.name, func(t *testing.T) {
234				so, se, code := runCLI(t, binary, state, tc.args...)
235				if code != 1 {
236					t.Fatalf("exit=%d want 1 (stdout=%q stderr=%q)", code, so, se)
237				}
238				// 结论没有写入：stdout 不得出现任何计票结果（JSON 模式也不得吐对象）。
239				if so != "" {
240					t.Fatalf("stdout must carry no tally result when nothing was written, got %q", so)
241				}
242				// stderr 必须保留具体保存原因。
243				if !strings.Contains(se, "permission denied") {
244					t.Fatalf("stderr must carry the concrete save cause, got %q", se)
245				}
246				// 不能误报“投票尚未截止”（截止时刻 200 本就允许计票）。
247				if strings.Contains(se, "still open") {
248					t.Fatalf("a deadline-reached tally must not be reported as still open: %q", se)
249				}
250				// 不能说成结论已写入/持久性未确认——这是“尚未写入”的失败。
251				if strings.Contains(se, "written but durability not confirmed") {
252					t.Fatalf("pre-replacement failure must not claim the conclusion was written: %q", se)
253				}
254			})
255		}
256	
257		// 恢复保存条件：原文件字节未变、没有遗留临时文件。
258		if err := os.Chmod(filepath.Dir(state), 0o700); err != nil {
259			t.Fatalf("restore dir: %v", err)
260		}
261		if got, rerr := os.ReadFile(state); rerr != nil || string(got) != string(good) {
262			t.Fatalf("state file changed despite the pre-replacement save failure")
263		}
264		if leftovers, _ := filepath.Glob(filepath.Join(filepath.Dir(state), ".govflow-state-*")); len(leftovers) != 0 {
265			t.Fatalf("failed tally left temporary file(s): %v", leftovers)
266		}
267	
268		// 恢复后、重计前的查询：仍是 voting、无结论，票据与提案形状完整保留。
269		cliTallyAssertVoting(t, binary, state, id)
270	
271		// 210 再次计票才形成首次成功结论：600/400/1000 通过，首次计票时间为 210，
272		// 绝不沿用失败尝试的 200。
273		so, se, code := runCLI(t, binary, state, "tally", "--id", id, "--now", "210")
274		if code != 0 {
275			t.Fatalf("first successful tally after recovery exit=%d: %s", code, se)
276		}
277		if !strings.Contains(so, "for=600 against=400 turnout=1000 quorum=600 => passed (tallied_at=210)") {
278			t.Fatalf("first successful tally must be the 210 passed conclusion:\n%s", so)
279		}
280		cliTallyAssertPassed(t, binary, state, id, 210)
281	
282		// 再次计票（传入更晚的 300）始终返回首次 210 结论，不重新计票、不改时间。
283		ro, re, rc := runCLI(t, binary, state, "tally", "--id", id, "--now", "300", "--json")
284		if rc != 0 || !strings.Contains(ro, `"passed": true`) || !strings.Contains(ro, `"tallied_at": 210`) {
285			t.Fatalf("repeat tally must return the first 210 conclusion, exit=%d stderr=%s:\n%s", rc, re, ro)
286		}
287		cliTallyAssertPassed(t, binary, state, id, 210)
288		cliTallyAssertFundsUntouched(t, binary, state)
289	}
290	
291	// TestCLITallyDirSyncWrittenButUnconfirmed：首次计票时状态文件已替换成功、只在
292	// 随后的目录同步失败（目录可写可进入但不可读，0o300）。普通文本与 --json
293	// 两种模式都必须：
294	//   - 退出码 1，stdout 仍没有计票结果（JSON 模式也不得吐结论对象）；
295	//   - stderr 明确“已写入但持久性未确认”，并保留具体失败原因（permission denied），
296	//     不能说成投票尚未截止；
297	//   - 恢复正常读取条件后，查询应看到 passed 与 tallied_at=200 的完整结论；
298	//   - 210 再次计票正常返回已有的 200 结论，不改成 210，也不把已通过提案退回 voting。
299	//
300	// 每种输出模式使用各自独立的状态文件：第一个进程的原子改名已经把结论写入，
301	// 之后的进程会直接读到已保存结论并成功返回，因此“失败当次”的输出判定必须在
302	// 一份全新状态上、只触发一次。全过程计票不执行转账，资金不变、无执行凭据。
303	func TestCLITallyDirSyncWrittenButUnconfirmed(t *testing.T) {
304		binary := buildCLI(t)
305	
306		for _, tc := range []struct {
307			name      string
308			failArgs  func(id string) []string
309			retryArgs func(id string) []string
310			wantOut   string
311		}{
312			{
313				name:      "text",
314				failArgs:  func(id string) []string { return []string{"tally", "--id", id, "--now", "200"} },
315				retryArgs: func(id string) []string { return []string{"tally", "--id", id, "--now", "210"} },
316				wantOut:   "for=600 against=400 turnout=1000 quorum=600 => passed (tallied_at=200)",
317			},
318			{
319				name: "json",
320				failArgs: func(id string) []string {
321					return []string{"tally", "--id", id, "--now", "200", "--json"}
322				},
323				retryArgs: func(id string) []string {
324					return []string{"tally", "--id", id, "--now", "210", "--json"}
325				},
326				wantOut: `"tallied_at": 200`,
327			},
328		} {
329			t.Run(tc.name, func(t *testing.T) {
330				state := filepath.Join(t.TempDir(), "treasury.json")
331				const id = "gip-tally-cli-sync"
332				cliTallyInit(t, binary, state, id)
333	
334				// 0300：临时文件写入/改名成功，只有随后的目录 fsync 失败。
335				makeDirSyncFail(t, state)
336				so, se, code := runCLI(t, binary, state, tc.failArgs(id)...)
337				if code != 1 {
338					t.Fatalf("exit=%d want 1 (stdout=%q stderr=%q)", code, so, se)
339				}
340				// 这次调用不报告成功计票结果：stdout 为空（JSON 模式同样不吐对象）。
341				if so != "" {
342					t.Fatalf("stdout must carry no tally result on the durability-uncertain call, got %q", so)
343				}
344				// stderr 必须明确“已写入但持久性未确认”并保留具体原因。
345				if !strings.Contains(se, "state written but durability not confirmed") {
346					t.Fatalf("stderr must state the conclusion was written but durability unconfirmed, got %q", se)
347				}
348				if !strings.Contains(se, "permission denied") {
349					t.Fatalf("stderr must preserve the concrete save cause, got %q", se)
350				}
351				if strings.Contains(se, "still open") {
352					t.Fatalf("a deadline-reached tally must not be reported as still open: %q", se)
353				}
354	
355				// 恢复正常读取条件：结论其实已随原子改名写入，无遗留临时文件。
356				if err := os.Chmod(filepath.Dir(state), 0o700); err != nil {
357					t.Fatalf("restore dir: %v", err)
358				}
359				if leftovers, _ := filepath.Glob(filepath.Join(filepath.Dir(state), ".govflow-state-*")); len(leftovers) != 0 {
360					t.Fatalf("dir-sync failure left temporary file(s): %v", leftovers)
361				}
362	
363				// 全新进程查询：passed 与 tallied_at=200 的完整结论，票据/成员/委托/动作保留。
364				cliTallyAssertPassed(t, binary, state, id, 200)
365	
366				// 210 再次计票：正常（退出码 0）返回已写入的 200 结论，不改成 210。
367				ro, re, rc := runCLI(t, binary, state, tc.retryArgs(id)...)
368				if rc != 0 {
369					t.Fatalf("repeat tally after recovery exit=%d: %s", rc, re)
370				}
371				if !strings.Contains(ro, tc.wantOut) {
372					t.Fatalf("repeat tally must return the already-written 200 conclusion:\n%s", ro)
373				}
374				if strings.Contains(ro, "tallied_at=210") || strings.Contains(ro, `"tallied_at": 210`) {
375					t.Fatalf("repeat tally must not move the first tally time to 210:\n%s", ro)
376				}
377				// 已通过提案不退回 voting，仍是 passed/200；票据、资金记录一致。
378				cliTallyAssertPassed(t, binary, state, id, 200)
379				cliTallyAssertFundsUntouched(t, binary, state)
380			})
381		}
382	}
383

